<?php
require_once __DIR__.'/../../includes/accounting_ui.php';
$id=(int)($_GET['id']??0);try{$invoice=$ac->record('ac_invoices',$id);}catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),404);}
acHandle(function()use($ac,$id){if(($_POST['action']??'')==='issue'){$ac->issueInvoice($id,(string)($_POST['revision']??''));return null;}if(($_POST['action']??'')==='advance'){$ac->applyAdvance(array_replace($_POST,['invoice_id'=>$id]));return null;}if(($_POST['action']??'')==='credit'){$ac->creditInvoice($_POST+['invoice_id'=>$id]);return null;}throw new InvalidArgumentException('Choose a supported invoice action.');},'invoice',['id'=>$id]);
$document=$ac->invoiceDocument($id);$invoice=$document['invoice'];$items=$document['items'];$balance=$ac->invoiceBalance($id);$schoolInfo=$document['school'];$class=$document['class'];$student=$document['student'];$year=$document['year'];$section=$document['section'];$previous=$invoice['student_id']?$ac->outstanding((int)$invoice['student_id'])-$balance:0;$paid=(int)$invoice['total_minor']-$balance;ob_start();
?>
<div class="d-flex gap-2 flex-wrap mb-3 no-print"><button class="btn btn-primary" data-erp-click="accounting-invoice-action-0" data-erp-click-args="<?= schoolPageActionArgs("accounting-invoice",[]) ?>">Print / Save PDF</button><label>Paper<select class="form-select" id="paperSize"><option>A4</option><option>A5</option><option value="80mm">80 mm</option></select></label><?php if($invoice['student_id']): ?><a class="btn btn-outline-primary" href="<?= acUrl('payments',['student'=>$invoice['student_id']]) ?>">Collect payment</a><a class="btn btn-outline-secondary" href="<?= acUrl('student',['student'=>$invoice['student_id']]) ?>">Student account</a><?php endif; ?></div>
<article class="ac-document"><header class="ac-document-header"><?php if($schoolInfo['logo']): ?><img src="<?= APP_URL ?>/uploads/<?= rawurlencode(basename($schoolInfo['logo'])) ?>" alt="School logo"><?php endif; ?><div><h2><?= sanitize($schoolInfo['name_en']) ?></h2><p class="mb-0"><?= sanitize($schoolInfo['address']??'') ?><br><?= sanitize(($schoolInfo['phone']??'').' · '.($schoolInfo['email']??'')) ?></p><?php if($document['pan_number']): ?><small><?= $document['tax_registered']?'Tax registration':'PAN' ?>: <?= sanitize($document['pan_number']) ?></small><?php endif; ?></div></header>
<h3><?= $invoice['status']==='draft'?'DRAFT — not an issued invoice':($invoice['status']==='void'?'VOID INVOICE':'INVOICE') ?> <?= sanitize($invoice['number']?:'#'.$id) ?></h3>
<div class="row"><div class="col-6"><strong><?= sanitize($invoice['customer_name']) ?></strong><p><?= sanitize($student['student_id']??'') ?> · <?= sanitize($class['name']??'External customer') ?> <?= sanitize($section['name']??'') ?><br><?php if($year): ?>Academic year: <?= sanitize((string)$year['year_bs']) ?> BS / <?= sanitize((string)$year['year_ad']) ?> AD<br><?php endif; ?><?= sanitize($invoice['guardian_name']??'') ?><br><?= sanitize(($invoice['phone']??'').' '.$invoice['address']) ?></p></div><div class="col-6"><p>Bill date: <?= sanitize(schoolDateLabel($invoice['bill_date'])) ?><br>Due: <?= sanitize(schoolDateLabel($invoice['due_date'])) ?><br>Billing period: <?= sanitize($invoice['billing_period']?:'Manual') ?></p></div></div><p><?= sanitize($invoice['description']??'') ?></p>
<table><thead><tr><th>SN</th><th>Particular</th><th>Qty</th><th class="money">Rate</th><th class="money">Amount</th></tr></thead><tbody><?php foreach($items as $n=>$r): ?><tr><td><?= $n+1 ?></td><td><?= sanitize($r['particular']) ?></td><td><?= rtrim(rtrim(number_format((int)$r['quantity_milli']/1000,3,'.',''),'0'),'.') ?></td><td class="money"><?= acMoney((int)$r['rate_minor']) ?></td><td class="money"><?= acMoney((int)$r['total_minor']) ?></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td>1</td><td colspan="3">Verified opening due (not current-period revenue)</td><td class="money"><?= acMoney((int)$invoice['total_minor']) ?></td></tr><?php endif; ?></tbody></table>
<div class="summary"><?php foreach(['Subtotal'=>'subtotal_minor','Discount'=>'discount_minor','Tax'=>'tax_minor','Total'=>'total_minor'] as $label=>$key): ?><p><span><?= $label ?></span><strong><?= acMoney((int)$invoice[$key]) ?></strong></p><?php endforeach; ?><p><span>Paid / credited / advance applied</span><strong><?= acMoney($invoice['status']==='draft'?0:$paid) ?></strong></p><p><span>Invoice remaining</span><strong><?= acMoney($balance) ?></strong></p><p><span>Other outstanding invoices</span><strong><?= acMoney($previous) ?></strong></p><p><span>Total account outstanding</span><strong><?= acMoney($previous+$balance) ?></strong></p></div>
<p><?= sanitize(acWords((int)$invoice['total_minor'])) ?></p><p>Status: <?= sanitize(ucwords(str_replace('_',' ',$ac->invoiceStatus($invoice)))) ?></p><footer class="print-signatures"><?= printUserSignature($db,(int)$school,(int)($invoice['created_by']??0),'Prepared by') ?><?= printSignature($schoolInfo['principal_name']??'','Authorized by',$schoolInfo['principal_signature']??null) ?></footer></article>
<?php if($invoice['status']==='draft'&&$ac->can('invoice')): ?><div class="no-print mt-3"><?php ?><a class="btn btn-outline-secondary mb-3" href="<?= acUrl('create_bill',['id'=>$id]) ?>">Edit draft</a><?php acForm('issue','Review and issue this draft'); ?><input type="hidden" name="revision" value="<?= sanitize(invoiceRevision($invoice)) ?>"><?php acSubmit('Issue invoice'); ?></div><?php endif; ?>
<?php if($invoice['status']==='issued'&&$invoice['student_id']&&$ac->can('advance')): ?><details class="no-print my-3"><summary>Apply available advance (<?= acMoney($ac->advanceBalance((int)$invoice['student_id'])) ?>)</summary><?php acForm('advance');acInput('amount','Advance amount (NPR)','0.00','number');acInput('date','Allocation date',date('Y-m-d'),'date');acSubmit('Apply advance'); ?></details><?php endif; ?>
<?php if($invoice['status']==='issued'&&$ac->can('credit')): ?><details class="no-print my-3"><summary>Credit note / cancellation (administrator approval)</summary><?php acForm('credit');acInput('amount','Credit amount (NPR)','0.00','number');acInput('date','Credit date',date('Y-m-d'),'date');acInput('reason','Reason'); ?><details class="my-3"><summary>Optional: credit selected bill lines</summary><p>Leave blank for proportional allocation. Selected amounts must add up to the total credit entered above.</p><?php foreach($items as $line):acInput('line_amounts['.$line['id'].']',$line['particular'].' — credit incl. tax (NPR)','','number',false);endforeach; ?></details><label><input type="checkbox" name="void" value="1"> Void completely unpaid invoice</label><div class="alert alert-warning mt-2">Original values are retained. Credits reduce unpaid dues first; a paid portion becomes an approved refund payable, never a negative student balance.</div><label><input type="checkbox" name="confirm" value="1" required> Confirm this financial correction</label><?php acSubmit('Approve credit'); ?></details><?php endif; ?>
<div class="card card-body mt-3 no-print"><h4>Credit notes / corrections</h4><?php $credits=$ac->rows('SELECT id,number,credit_date,amount_minor,refund_minor FROM ac_credits WHERE school_id=? AND invoice_id=? ORDER BY id',[$school,$id]);foreach($credits as $credit): ?><p><a href="<?= acUrl('credit',['id'=>$credit['id']]) ?>"><?= sanitize($credit['number']) ?></a> · <?= acMoney((int)$credit['amount_minor']) ?> · <?= sanitize(schoolDateLabel($credit['credit_date'],'both','ymd')) ?><?php if($credit['refund_minor']): ?> · Includes refund payable <?= acMoney((int)$credit['refund_minor']) ?><?php endif; ?></p><?php endforeach;if(!$credits): ?><p class="mb-0 text-muted">No approved corrections for this invoice.</p><?php endif; ?></div>
<style id="paperStyle"></style><?php schoolPageModule("accounting-invoice"); ?>
<?php acRender('Bill preview',ob_get_clean());
